/**
 * vettingScoreDetails — GENERATED display copy: the per-dimension "why this score"
 * (the assessment's recorded rationale) and "what holds it back" (its recorded
 * limiting fact), mirrored VERBATIM from the assessment modules listed per block.
 *
 * Copy may use **double asterisks** for inline emphasis; the drawer renders those as
 * bold and shows all other text verbatim.
 *
 * NOTE: blocks marked HAND-AUTHORED carry user-facing copy approved by the product
 * owner and must be preserved when regenerating the rest.
 *
 * Regenerate whenever an assessment changes (scratchpad genScoreDetails script) —
 * the Vetting page imports no scoring module, so this file carries the record.
 * Rationales written for internal governance (over 700 chars) are omitted;
 * the limiting fact remains.
 */

export interface DimensionScoreDetail {
  /** Why the dimension sits at its score — the assessment's recorded rationale. */
  why?: string;
  /** What keeps it from scoring higher — the assessment's recorded limiting fact. */
  held?: string;
}

